import { AsyncLocalStorage } from 'node:async_hooks';

export const requestStore = new AsyncLocalStorage();

export function withRequestContext(ctx, fn) { return requestStore.run(ctx, fn); }
export function requestId() { return requestStore.getStore()?.requestId; }

// at the edge, before any handler:
app.use((req, res, next) => withRequestContext({ requestId: idFor(req) }, () => next()));
